<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\Template\Application\Service\Visibility\TemplateVisibilityService;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateReadGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateFilter;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateCursor;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVisibilityService $visibility,
        private readonly TemplateReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Template");
        $span = $this->startSpan("Check allow of list usecase for Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(TemplateFilter $filter): int
    {
        $this->logDebug("Run list usecase for Template");
        $span = $this->startSpan("Run list usecase for Template");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Template');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(TemplateFilter $filter, ?TemplateCursor $cursor = null): TemplateAttributesSlide
    {
        $this->logDebug("Run list usecase for Template");
        $span = $this->startSpan("Run list usecase for Template");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new TemplateAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
